.g-moto-guide-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
.g-moto-guide-card{background:#fff}
.g-moto-guide-card .g-card-media{aspect-ratio:16/10}
.g-moto-guide-card .g-card-body h3{font-size:11px;line-height:1.55}
.g-moto-guide-card .g-card-body p{font-size:8px}

@media(max-width:980px){
  .g-moto-origin-groups{grid-template-columns:1fr}
  .g-moto-guide-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:650px){
  .g-moto-brand-universe,.g-moto-guide-zone{padding:15px;border-radius:15px}
  .g-moto-brand-universe .g-section-head,.g-moto-guide-zone .g-section-head{align-items:flex-start;flex-direction:column}
  .g-moto-brand-chips{grid-template-columns:1fr}
  .g-moto-guide-grid{grid-template-columns:1fr}
  .g-moto-guide-card{display:grid;grid-template-columns:105px minmax(0,1fr)}
  .g-moto-guide-card .g-card-media{height:100%;aspect-ratio:auto}
  .g-moto-guide-card .g-card-body{padding:10px}
  .g-moto-guide-card .g-card-body p{display:none}
}


/* Showroom editorial rebuild */
.a3-directory-cta{margin:28px 0;padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#0a1826,#17334b);color:#fff}
.a3-directory-cta strong{display:block;font-family:"Alexandria";font-size:17px;margin-bottom:6px}
.a3-directory-cta p{margin:0 0 12px;color:#c9d5df;font-size:13px;line-height:1.8}
.a3-directory-cta a{display:inline-flex;padding:9px 13px;border-radius:9px;background:var(--g-orange);color:#fff;font-size:11px;font-weight:900}
.a3-editorial-sources{margin:30px 0 8px;padding:18px;border-radius:14px;background:#f6f8fa;border:1px solid #e0e6eb}
.a3-editorial-sources h2{margin-top:0!important}
.a3-editorial-sources ul{margin-bottom:10px}
.a3-editorial-sources li{margin:7px 0}
.a3-editorial-sources a{color:#176ed7;text-decoration:underline}
.a3-editorial-sources small{color:#6f7e8b;line-height:1.7}


/* =========================================================
   A3tal Global 1.7.2 — Showroom guide category image hardening
   ========================================================= */
.g-showroom-editorial-hero{padding:42px 0 34px;background:linear-gradient(135deg,#081522,#15324a);color:#fff}
.g-showroom-editorial-hero span{display:inline-block;color:#ff9f83;font-size:9px;font-weight:900;letter-spacing:.08em}
.g-showroom-editorial-hero h1{font-family:"Alexandria";font-size:38px;line-height:1.25;margin:7px 0 10px;color:#fff}
.g-showroom-editorial-hero p{max-width:760px;margin:0;color:#c4d0da;font-size:12px;line-height:1.8}
.g-showroom-editorial-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}
.g-showroom-editorial-actions a{display:inline-flex;padding:9px 12px;border-radius:9px;background:#fff;color:#0d2235;font-size:9px;font-weight:900}
.g-showroom-editorial-actions a:first-child{background:var(--g-orange);color:#fff}

.g-showroom-editorial-main{padding-top:28px;padding-bottom:60px}
.g-showroom-editorial-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.g-showroom-editorial-card{display:grid;grid-template-columns:46% minmax(0,1fr);min-width:0;background:#fff;border:1px solid var(--g-line);border-radius:18px;overflow:hidden;box-shadow:0 10px 30px rgba(12,31,49,.06)}
.g-showroom-editorial-media{position:relative;display:block!important;min-height:260px;background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important;overflow:hidden}
.g-showroom-editorial-media img{display:block!important;width:100%!important;height:100%!important;min-height:260px!important;object-fit:cover!important;opacity:1!important;visibility:visible!important;position:absolute!important;inset:0!important}
.g-showroom-editorial-number{position:absolute;z-index:2;top:12px;right:12px;display:inline-flex;align-items:center;justify-content:center;min-width:36px;height:30px;padding:0 8px;border-radius:999px;background:rgba(7,20,32,.82);color:#fff;font-size:9px;font-weight:900;backdrop-filter:blur(7px)}
.g-showroom-editorial-body{min-width:0;padding:17px 17px 16px}
.g-showroom-editorial-kicker{color:var(--g-orange);font-size:8px;font-weight:900;margin-bottom:7px}
.g-showroom-editorial-body h2{font-family:"Alexandria";font-size:16px;line-height:1.55;margin:0 0 8px}
.g-showroom-editorial-body h2 a{color:var(--g-ink)}
.g-showroom-editorial-body p{margin:0 0 12px;color:#697886;font-size:10px;line-height:1.75}
.g-showroom-editorial-meta{display:flex;gap:10px;flex-wrap:wrap;color:#8b97a2;font-size:7px;margin-bottom:12px}
.g-showroom-editorial-read{display:inline-flex;font-size:8px;font-weight:900;color:#176ed7}
.g-showroom-editorial-directory{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:34px;padding:24px;border-radius:18px;background:#0b1c2b;color:#fff}
.g-showroom-editorial-directory span{color:#ff9b7e;font-size:8px;font-weight:900}
.g-showroom-editorial-directory h2{font-family:"Alexandria";font-size:20px;margin:4px 0 7px;color:#fff}
.g-showroom-editorial-directory p{margin:0;max-width:720px;color:#b9c7d1;font-size:10px;line-height:1.75}
.g-showroom-editorial-directory>a{flex:0 0 auto;display:inline-flex;padding:10px 13px;border-radius:9px;background:var(--g-orange);color:#fff;font-size:9px;font-weight:900}

@media(max-width:980px){
  .g-showroom-editorial-grid{grid-template-columns:1fr}
  .g-showroom-editorial-card{grid-template-columns:40% minmax(0,1fr)}
}
@media(max-width:650px){
  .g-showroom-editorial-hero{padding:28px 0 24px}
  .g-showroom-editorial-hero h1{font-size:28px}
  .g-showroom-editorial-grid{gap:12px}
  .g-showroom-editorial-card{grid-template-columns:1fr}
  .g-showroom-editorial-media{min-height:220px;aspect-ratio:16/10}
  .g-showroom-editorial-media img{min-height:220px!important}
  .g-showroom-editorial-body{padding:14px}
  .g-showroom-editorial-body h2{font-size:14px}
  .g-showroom-editorial-directory{align-items:flex-start;flex-direction:column;padding:18px}
}

/* A3tal 1.7.3 audit polish */
.g-platform-empty>.g-icon{display:grid;place-items:center;width:44px;height:44px;margin:0 auto;color:var(--g-orange)}
.g-platform-empty>.g-icon svg{width:34px;height:34px}
.g-dtc-search-results{border-top:0;padding-top:0;margin-top:18px}
.g-os-car-head>span .g-icon svg,.g-place-mega>span .g-icon svg,.g-moto-teaser-grid span .g-icon svg{width:25px;height:25px}
.g-place-mega>span,.g-moto-teaser-grid span{color:#29445e}
@media(max-width:650px){.g-hero-platform h1{font-size:33px}.g-platform-launcher small{font-size:8px}.g-hero-action-row small{font-size:8px}}

/* persistent article views */
.g-article-views,.g-views-mini{display:inline-flex!important;align-items:center;gap:4px}
.g-article-views .g-icon svg{width:15px;height:15px}
.g-article-views b{font-weight:700}
.g-views-mini .g-icon svg{width:12px;height:12px}
.g-views-mini b{font-weight:700}

/* A3tal 1.7.4 audit fixes */
.g-result-type{display:inline-flex;margin-bottom:7px;padding:3px 7px;border-radius:999px;background:#fff2ed;color:#d7441e;font-size:8px;font-weight:900}
.g-related-model-box{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:0 0 20px;padding:14px 16px;border:1px solid #dfe7ee;border-right:4px solid var(--g-orange);border-radius:12px;background:#f8fbfd}
.g-related-model-box>div{display:flex;flex-direction:column;gap:2px}
.g-related-model-box small{font-size:9px;color:#778596}
.g-related-model-box strong{font-family:"Alexandria";font-size:14px;color:#15283d}
.g-related-model-box span{font-size:10px;color:var(--g-orange);font-weight:800}
.g-related-model-box>a{flex:0 0 auto;padding:8px 11px;border-radius:8px;background:var(--g-dark);color:#fff;font-size:9px;font-weight:900}
.g-os-car-head>b{font-size:8px!important;white-space:nowrap}
@media(max-width:600px){.g-related-model-box{align-items:flex-start;flex-direction:column}.g-related-model-box>a{width:100%;justify-content:center}.g-article-head h1{font-size:29px}}
